function validateMigrated(x){const errs=[],ids=new Set(),catIds=new Set(),subIds=new Set();for(const g of x.categories){if(catIds.has(g.id))errs.push("カテゴリID重複");catIds.add(g.id);for(const s of g.subs||[]){if(subIds.has(s.id))errs.push("小分類ID重複");subIds.add(s.id)}}const med=x.categories.filter(g=>g.name==="医療・健康");if(med.length!==1)errs.push("医療・健康カテゴリ重複");if(med[0])for(const n of MEDICAL_SUBS)if(!med[0].subs.some(s=>s.name===n))errs.push(`医療小分類不足 ${n}`);for(const [gname,names] of [["食費",["ラーメン・つけ麺・油そば","冷凍食品","スイーツ"]],["交通",["車費用","バイク費用","自転車費用"]]]){const g=x.categories.find(c=>c.name===gname);if(!g)errs.push(`${gname}カテゴリ不足`);else for(const n of names)if(!g.subs.some(s=>s.name===n))errs.push(`${gname}小分類不足 ${n}`)}for(const t of x.transactions){if(!t.id||ids.has(t.id))errs.push("重複または空の取引ID");ids.add(t.id);if(t.type==="expense"&&!t.relationGroupId)errs.push(`支出 ${t.id} のrelationGroupIdなし`);if(t.linkedExpenseId&&!x.transactions.some(e=>e.id===t.linkedExpenseId&&e.type==="expense"))errs.push(`linkedExpenseId参照切れ ${t.id}`);if(t.parentExpenseId&&!x.transactions.some(e=>e.id===t.parentExpenseId&&e.type==="expense"))errs.push(`parentExpenseId参照切れ ${t.id}`);if(t.categoryId&&!catIds.has(t.categoryId))errs.push(`categoryId不正 ${t.id}`);if(t.subcategoryId&&!subIds.has(t.subcategoryId))errs.push(`subcategoryId不正 ${t.id}`);if(!x.months[monthOf(t.date)])errs.push(`月データ不足 ${t.date}`)}if(x.accounts.filter(a=>a.id==="pasmo"||String(a.name||"").toUpperCase()==="PASMO").length!==1)errs.push("PASMO口座重複");return errs}
function openDBNamed(name,version){return new Promise((res,rej)=>{const r=version?indexedDB.open(name,version):indexedDB.open(name);let blocked=false;r.onsuccess=()=>{const db=r.result;if(blocked){db.close();return}db.onversionchange=()=>db.close();res(db)};r.onerror=()=>rej(r.error);r.onblocked=()=>{blocked=true;rej(new Error("データベース更新がブロックされています。アプリを完全に閉じて再起動してください。"))}})}
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DBNAME,SCHEMA_VERSION);let blocked=false;r.onupgradeneeded=()=>{const db=r.result;[["meta","key"],["settings","key"],["accounts","id"],["categories","id"],["favorites","id"],["months","month"],["transactions","id"]].forEach(([n,k])=>{if(!db.objectStoreNames.contains(n))db.createObjectStore(n,{keyPath:k})})};r.onsuccess=()=>{const db=r.result;if(blocked){db.close();return}db.onversionchange=()=>db.close();res(db)};r.onerror=()=>rej(r.error);r.onblocked=()=>{blocked=true;rej(new Error("データベース更新がブロックされています"))}})}
