function defaultDate(){return getMonth()===curMonth()?dstr(now()):`${getMonth()}-01`}function recentChips(){return(state.recentCategories||[]).slice(0,5).map(sid=>{for(const g of sortedCategories(false)){const s=g.subs.find(x=>x.id===sid);if(s)return`<button type="button" class="chip" data-cat="${g.id}|||${s.id}">${esc(s.name)}</button>`}return""}).join("")}function favoriteChips(){return [...state.favorites].sort((a,b)=>(a.order??9999)-(b.order??9999)).filter(f=>{const{g,s}=findCat(f.categoryId,f.subcategoryId);return g&&s&&!g.archived&&g.active!==false&&!s.archived&&s.active!==false}).map(f=>`<button type="button" class="chip" data-fav="${f.id}">${esc(f.name)} ${yen(f.amount)}</button>`).join("")}function markRecent(sid){state.recentCategories=[sid,...state.recentCategories.filter(x=>x!==sid)].slice(0,8)}function linkedReserve(expId){return state.transactions.find(t=>t.type==="credit_reserve"&&(t.autoLinked||t.linkedExpenseId===expId)&&t.linkedExpenseId===expId)}
