function makeClosedSnapshot(m){const as=`${m}-${pad(daysInMonth(m))}`,p=paymentTotals(m),b=balanceAsOf(as),cat={},sub={},pay={},counts={};for(const t of expensesOrigin(m)){const net=expenseNetAt(t,as);cat[t.categoryId||"other"]=(cat[t.categoryId||"other"]||0)+net;sub[t.subcategoryId||"other"]=(sub[t.subcategoryId||"other"]||0)+net;pay[t.from||"other"]=(pay[t.from||"other"]||0)+net;counts[t.subcategoryId||"other"]=(counts[t.subcategoryId||"other"]||0)+1}return{budget:monthBudget(m),grossSpend:grossSpend(m),netSpendAtClose:sum(Object.values(cat)),remainingAtClose:monthBudget(m)-sum(Object.values(cat)),cashSpend:p.cash,rakutenSpend:p.rakuten,creditSpend:p.credit,topupAmount:sum(txMonth(m).filter(t=>t.type==="topup").map(t=>t.amount)),walletBalance:b.wallet||0,homeCashBalance:b.homecash||0,rakutenPayBalance:b.rakutenpay||0,creditLiability:liabilityAsOf(as),usableBalanceAtClose:usableBalanceAsOf(as),budgetDifferenceAtClose:usableBalanceAsOf(as)-(monthBudget(m)-sum(Object.values(cat))),categoryTotals:cat,subcategoryTotals:sub,paymentTotalsByAccount:pay,subcategoryCounts:counts,closedAt:Date.now()}}
