function historyDetail(t){
  if(t.type==="expense")return t.detail||t.item||catName(t);
  if(isEmoneyCharge(t))return `電子マネーチャージ：${acctName(t.from)} → ${acctName(t.to)}（支出ではない）`;
  if(t.type==="refund"){
    const p=state.transactions.find(x=>x.id===t.parentExpenseId);
    return `${p?.detail||p?.item||catName(t)}の返金 → ${acctName(t.to)}`;
  }
  if(t.type==="credit_remainder_reset")return `前月のクレカ端数 ${yen(t.amount)} を銀行残高へ吸収（翌月へ繰り越さない）`;if(t.type==="adjustment")return `${acctName(t.to)} 残高調整${Number(t.delta||0)>=0?" +": " "}${yen(t.delta||0)}`;
  return t.detail||"-"
}
