function renderCreditSettings(){const el=document.getElementById("creditSettingsPanel"),badge=document.getElementById("creditSettingsBadge");if(!el||!badge)return;const c=creditAccount(),li=liabilityAsOf(dstr(now())),rv=reserveTotalAsOf(dstr(now())),has=hasCreditActivity(),pi=nextPaymentInfo();badge.textContent=`未払い ${yen(li)}`;badge.className=`badge ${li?"warn":"ok"}`;el.innerHTML=`<div class="credit-settings-grid"><div class="credit-summary-box"><div class="small">現在の未払い残高</div><div class="big">${yen(li)}</div><div class="small">開始未払い ${yen(c?.start||0)}</div></div><div class="credit-summary-box"><div class="small">クレカ用確保</div><div class="big">${yen(rv)}</div><div class="small">銀行残高は管理しません</div></div></div><div class="form-grid" style="margin-top:12px"><label>締め日<select id="creditClosingDay"><option value="last" ${c?.closingDay==="last"?"selected":""}>毎月末日</option>${[5,10,15,20,25,28].map(n=>`<option value="${n}" ${String(c?.closingDay)===String(n)?"selected":""}>毎月${n}日</option>`).join("")}</select></label><label>支払日（翌月）<input id="creditPaymentDay" type="number" min="1" max="28" value="${Number(c?.paymentDay||27)}"></label>${!has?`<label>開始時の未払い残高<input id="creditInitialLiability" type="number" min="0" value="${Number(c?.start||0)}"></label>`:'<div><div class="small">開始負債は運用開始後は直接変更しません。</div><button id="openLiabilityAdjust" type="button" class="secondary" style="margin-top:8px">未払い残高を合わせる</button></div>'}</div><div class="small" style="margin-top:10px">カード利用分を財布・家の現金から銀行へ補填したら「クレカ用に確保」で記録します。</div><div style="margin-top:12px"><label>表示色</label>${colorPickerHTML(c?.color||ACCOUNT_COLORS.credit,"creditColor")}</div><button id="saveCreditSettings" class="primary" style="width:100%;margin-top:12px">カード設定を保存</button>`;bindColorPickers(el);document.getElementById("saveCreditSettings").onclick=saveCreditSettings;document.getElementById("openLiabilityAdjust")?.addEventListener("click",openLiabilityAdjust)}
