document.querySelectorAll(".settings-tab").forEach(b=>b.onclick=()=>{document.querySelectorAll(".settings-tab,.settings-pane").forEach(x=>x.classList.remove("active"));b.classList.add("active");document.getElementById(`pane-${b.dataset.pane}`).classList.add("active")});document.getElementById("saveBasic").onclick=async()=>{const was=state.settings.carryover;state.settings.cashBudget=Number(document.getElementById("setCashBudget").value||0);state.settings.rakutenBudget=Number(document.getElementById("setRakutenBudget").value||0);state.settings.carryover=document.getElementById("setCarry").value==="on";state.settings.insufficient=document.getElementById("setInsufficient").value;for(const ms of Object.values(state.months))if(!ms.initialized&&!ms.closed){ms.cashBudget=state.settings.cashBudget;ms.rakutenBudget=state.settings.rakutenBudget;if(!state.settings.carryover)ms.carryover=0}if(was&&!state.settings.carryover)for(const ms of Object.values(state.months))if(!ms.closed)ms.carryover=0;await persist();renderAll();toast("✓ 基本設定を保存しました")};
function editAccount(id=null){const a=id?acct(id):null;if(a?.type==="liability"){toast("クレジットカード設定は下の専用欄から変更してください。");return}modal(a?"口座の詳細設定":"口座を追加",`<form id="accForm"><p class="muted">残高はこの画面では変更しません。「設定 → 残高・口座」の一覧で変更してください。</p><div class="form-grid"><label>名前<input id="accName" value="${esc(a?.name||"")}"></label><label>種類<select id="accType">${["cash","emoney","other"].map(t=>`<option value="${t}" ${a?.type===t?"selected":""}>${t}</option>`).join("")}</select></label><label>残高追跡<select id="accTrack"><option value="on" ${a?.trackBalance!==false?"selected":""}>ON</option><option value="off" ${a?.trackBalance===false?"selected":""}>OFF</option></select></label><label>表示<select id="accActive"><option value="yes" ${a?.active!==false?"selected":""}>有効</option><option value="no" ${a?.active===false?"selected":""}>非表示</option></select></label><label>今月使える残高に含める<select id="accBudgetIncluded"><option value="yes" ${a?.budgetIncluded?"selected":""}>ON</option><option value="no" ${!a?.budgetIncluded?"selected":""}>OFF</option></select></label><label>ホームに表示<select id="accHome"><option value="yes" ${a?.showOnHome?"selected":""}>ON</option><option value="no" ${!a?.showOnHome?"selected":""}>OFF</option></select></label><div id="emoneySettingsBox" class="full"></div><div class="full"><label>表示色</label>${colorPickerHTML(a?.color||ACCOUNT_COLORS[a?.id]||"#38bdf8","accColor")}</div></div><div id="accMsg"></div><button class="primary" style="width:100%;margin-top:12px">保存</button></form>`);const renderEmoney=()=>{const box=document.getElementById("emoneySettingsBox"),isE=document.getElementById("accType").value==="emoney";box.innerHTML=isE?`<div class="form-grid"><label>低残高警告<select id="accLowWarn"><option value="on" ${a?.lowBalanceWarning!==false?"selected":""}>ON</option><option value="off" ${a?.lowBalanceWarning===false?"selected":""}>OFF</option></select></label><label>警告額<input id="accLowAmount" type="number" min="0" value="${Number(a?.lowBalanceWarningAmount??500)}"></label></div>`:""};document.getElementById("accType").onchange=renderEmoney;renderEmoney();bindColorPickers(document.getElementById("accForm"));document.getElementById("accForm").onsubmit=async e=>{e.preventDefault();const type=document.getElementById("accType").value,home=document.getElementById("accHome").value==="yes";if(home){const otherShown=state.accounts.filter(x=>x.id!==a?.id&&x.type!=="liability"&&x.showOnHome!==false&&x.active!==false).length;if(otherShown>=4){document.getElementById("accMsg").innerHTML='<div class="errorbox">ホームに表示できる残高は最大4口座です。</div>';return}}const o={id:a?.id||`acc_${uid()}`,name:document.getElementById("accName").value.trim(),type,start:a?.start||0,trackBalance:document.getElementById("accTrack").value==="on",active:document.getElementById("accActive").value==="yes",budgetIncluded:document.getElementById("accBudgetIncluded").value==="yes",free:document.getElementById("accBudgetIncluded").value==="yes",showOnHome:home,color:document.getElementById("accColor").value,lowBalanceWarning:type==="emoney"?document.getElementById("accLowWarn").value==="on":false,lowBalanceWarningAmount:type==="emoney"?Math.max(0,Number(document.getElementById("accLowAmount").value||0)):0};if(!o.name)return;const i=state.accounts.findIndex(x=>x.id===o.id);if(i>=0)state.accounts[i]=o;else state.accounts.push(o);await persist();closeModal();renderAll();toast(a?"✓ 口座設定を保存しました":"✓ 口座を追加しました")}}document.getElementById("addAccount").onclick=()=>editAccount();document.getElementById("addCategory").onclick=()=>openCategoryEditor();document.getElementById("addFavorite").onclick=()=>openFavoriteEditor();
async function saveCreditSettings(){const c=creditAccount();if(!c)return;c.color=document.getElementById("creditColor")?.value||c.color||ACCOUNT_COLORS.credit;c.closingDay=document.getElementById("creditClosingDay").value;c.paymentDay=Math.max(1,Math.min(28,Number(document.getElementById("creditPaymentDay").value||27)));const init=document.getElementById("creditInitialLiability");if(init&&!hasCreditActivity())c.start=Math.max(0,Number(init.value||0));await persist();renderAll();toast("✓ カード設定を保存しました")}function openLiabilityAdjust(){const current=liabilityAsOf(dstr(now()));modal("カード未払い残高を合わせる",`<form id="liabilityAdjustForm"><p class="muted">家計簿上 ${yen(current)} とカードアプリの実際の未払い残高を合わせます。</p><label>実際の未払い残高<input id="liabilityActual" type="number" min="0" value="${current}"></label><div id="liabilityAdjustMsg"></div><button class="primary" style="width:100%;margin-top:12px">差額を記録</button></form>`);document.getElementById("liabilityAdjustForm").onsubmit=async e=>{e.preventDefault();const actual=Math.max(0,Number(document.getElementById("liabilityActual").value||0)),diff=actual-current;if(!diff){closeModal();toast("変更はありません");return}const t={id:uid(),created:Date.now(),date:dstr(now()),type:"liability_adjustment",amount:Math.abs(diff),delta:diff,to:"credit",detail:"カード未払い残高調整"};state.transactions.push(t);undoOp={kind:"createIds",ids:[t.id]};await persist();closeModal();renderAll();toast(`✓ カード未払いを ${yen(actual)} に合わせました`,true)}}
