async function saveAccountBalances(){if(isClosed(curMonth())){document.getElementById("accountBalanceMsg").innerHTML='<div class="errorbox">今月は締め済みです。残高を変更するには締めを解除してください。</div>';return}const inputs=[...document.querySelectorAll("[data-balance-id]")],before=balanceAsOf(dstr(now())),created=[];let changed=0;for(const input of inputs){if(input.value==="")continue;const id=input.dataset.balanceId,a=acct(id);if(!a||a.type==="liability")continue;const desired=Number(input.value);if(!Number.isFinite(desired))continue;const current=Number(before[id]||0),diff=desired-current,edited=Number(input.dataset.original)!==desired;if(!edited)continue;if(a.trackBalance===false)a.trackBalance=true;if(Math.abs(diff)<0.0001)continue;const hasOwnHistory=state.transactions.some(t=>t.from===id||t.to===id);if(!hasOwnHistory){a.start=Number(a.start||0)+diff}else{const t={id:uid(),created:Date.now()+created.length,date:dstr(now()),type:"adjustment",amount:Math.abs(diff),delta:diff,to:id,detail:"残高・口座から残高を反映"};state.transactions.push(t);created.push(t.id)}changed++}await persist();undoOp=created.length?{kind:"createIds",ids:created}:null;renderAll();const msg=document.getElementById("accountBalanceMsg");if(msg)msg.innerHTML=`<div class="success">${changed?`${changed}口座の残高を反映しました。`:"変更はありませんでした。"}</div>`;toast(changed?"✓ 残高を反映しました":"残高に変更はありません")}document.getElementById("saveAccountBalances").onclick=saveAccountBalances;
